<script lang="ts">
 import SiteHeader from '$lib/SiteHeader.svelte';
 let {data}=$props();
 let e=$derived(data.entity as Record<string,any>);
 let connections=$derived(data.connections as Record<string,any>[]);
 let gets=$derived(data.gets as Record<string,any>);
 let rfx=$derived(gets?.rfx as Record<string,any>|null);
 let supplier=$derived(gets?.supplier as Record<string,any>|null);
 let regions=$derived((gets?.regions??[]) as Record<string,any>[]);
 let categories=$derived((gets?.categories??[]) as Record<string,any>[]);
 let suppliers=$derived((gets?.suppliers??[]) as Record<string,any>[]);
 let relatedRfx=$derived((gets?.relatedRfx??[]) as Record<string,any>[]);
 let sourceEvidence=$derived(data.sourceEvidence as Record<string,any>|null);
 let metadata=$derived(parseMetadata(e.metadata_json));
 let showAllSuppliers=$state(false);
 let showAllConnections=$state(false);
 let visibleSuppliers=$derived(showAllSuppliers?suppliers:suppliers.slice(0,20));
 let visibleConnections=$derived(showAllConnections?connections:connections.slice(0,20));
 let getsKind=$derived(metadata?.gets?.kind as string|undefined);
 let isCharityOfficerRecord=$derived(String(e.slug??'').startsWith('charities-officer-'));
 let isGetsAgencyRecord=$derived(!rfx&&!supplier&&(Boolean(gets?.agency)||getsKind==='agency'||connections.some((c)=>c.predicate==='ISSUED')));
 const relationshipLabels:Record<string,{out:string;in:string}>={OFFICER_OF:{out:'Officer of',in:'Officer'},ISSUED:{out:'Issued by',in:'Government tenders issued'},AWARDED_TO:{out:'Awarded to',in:'Successful supplier for'}};
 function parseMetadata(raw:unknown){try{return raw?JSON.parse(String(raw)):{};}catch{return {};}}
 function relationshipLabel(predicate:string,direction:string){const known=relationshipLabels[predicate];if(known)return direction==='out'?known.out:known.in;const fallback=String(predicate).replaceAll('_',' ').toLowerCase().replace(/^./,(c)=>c.toUpperCase());return direction==='out'?fallback:`Connected by ${fallback.toLowerCase()}`;}
 function cleanSupplierName(name:string){return String(name||'').replace(/^Supplier record — /,'').replace(/ — RFx .*$/,'');}
 function recordType(){if(rfx)return 'Government tender';if(supplier)return 'GETS supplier record';if(isGetsAgencyRecord)return 'Government agency';return isCharityOfficerRecord?'Charity officer record':String(e.entity_type).replace('_',' ');}
 function connectedRecordType(c:Record<string,any>){const meta=parseMetadata(c.connected_metadata_json);if(c.connected_gets_rfx_entity_id)return 'Government tender';if(c.connected_gets_supplier_entity_id)return 'GETS supplier record';if(meta?.gets?.kind==='agency')return 'Government agency';if(String(c.connected_slug??'').startsWith('charities-officer-'))return 'Charity officer record';const raw=String(c.connected_type??'Public record');if(raw==='charity')return 'Charity';if(raw==='company')return 'Company';if(raw==='person')return 'Person';return 'Public record';}
 function displayConnectedName(c:Record<string,any>){return c.connected_gets_supplier_entity_id?cleanSupplierName(c.connected_name):c.connected_gets_rfx_entity_id?String(c.connected_name||'').replace(/^Procurement record RFx [^—]+ — /,''):c.connected_name;}
 function nzbnSourceNote(value:unknown){const code=String(value??'').trim();const notes:Record<string,string>={MISSING:'NZBN not supplied in source data',SCIENTIFIC_NOTATION_LOSSY:'NZBN could not be reliably recovered from the source data',MALFORMED:'NZBN in source data was not in a usable format',OTHER_UNUSABLE:'NZBN in source data could not be reliably used for identification',VALID:'NZBN supplied in source data'};return notes[code]??(code?'NZBN source value could not be reliably used for identification':'NZBN not supplied in source data');}
 function valueOrMissing(value:unknown){return value===null||value===undefined||value===''?'Not supplied':String(value);}
 function isCharitySource(src:Record<string,any>|null){return String(src?.source_kind??'')==='charity';}
 function recordSourceIntro(src:Record<string,any>|null){return isCharitySource(src)?'This record comes from the New Zealand Charities Register.':'This record comes from a public source record.';}
 function sourcePublisher(src:Record<string,any>|null){return isCharitySource(src)?'Charities Services, Department of Internal Affairs':valueOrMissing(src?.publisher);}
 function recordSourceLinkText(src:Record<string,any>|null){return isCharitySource(src)?'View charity register record':'View source record';}
 function connectionPublisher(c:Record<string,any>){return c.publisher?String(c.publisher):'Public source';}
</script>
<svelte:head><title>{rfx?rfx.title:supplier?cleanSupplierName(e.canonical_name):e.canonical_name} · NZ Records</title></svelte:head>
<SiteHeader />
<main><p class="breadcrumb"><a href="/explore">Search records</a> / Record</p><section class="identity"><p class="type">{recordType()}</p><h1>{rfx?rfx.title:supplier?cleanSupplierName(e.canonical_name):e.canonical_name}</h1><p class="status">{rfx?valueOrMissing(rfx.award_type):supplier?'Not verified as a separate company record':isGetsAgencyRecord?'GETS source name only':e.status??'Status not supplied'}</p>{#if e.nzbn||e.company_number||rfx||supplier}<dl class="ids">{#if e.nzbn}<div><dt>NZBN</dt><dd>{e.nzbn}</dd></div>{/if}{#if e.company_number}<div><dt>Company number</dt><dd>{e.company_number}</dd></div>{/if}{#if rfx}<div><dt>RFx number</dt><dd>{rfx.rfx_id}</dd></div>{/if}{#if supplier}<div><dt>RFx number</dt><dd>{supplier.rfx_id}</dd></div>{/if}</dl>{/if}
{#if isCharityOfficerRecord}<aside class="note"><strong>About this record</strong><span>This is an officer record for one charity. The same person may have other records on this site, but we don't combine them unless we can be sure they're the same person.</span></aside>{/if}
{#if supplier}<aside class="note"><strong>About this supplier record</strong><span>This supplier information was published in a GETS tender record. It has not necessarily been matched to a company elsewhere in NZ Records.</span></aside>{/if}
{#if isGetsAgencyRecord}<aside class="note"><strong>About this agency record</strong><span>This agency name is taken from GETS. NZ Records has not yet matched this record with agency records from other data sources.</span></aside>{/if}</section>
{#if rfx}<section class="gets"><div class="heading"><h2>Government tender details</h2><span>{valueOrMissing(rfx.award_type)}</span></div><article><dl class="facts"><dt>RFx number</dt><dd>{rfx.rfx_id}</dd><dt>Title</dt><dd>{rfx.title}</dd><dt>Outcome</dt><dd>{valueOrMissing(rfx.award_type)}</dd><dt>Issued by</dt><dd><a href={`/record/${rfx.agency_entity_id}`}>{rfx.posting_agency}</a></dd><dt>Reported / expected value</dt><dd>{valueOrMissing(rfx.awarded_amount_raw)}</dd><dt>Open date</dt><dd>{valueOrMissing(rfx.open_date)}</dd><dt>Close date</dt><dd>{valueOrMissing(rfx.close_date)}</dd><dt>Awarded date</dt><dd>{valueOrMissing(rfx.awarded_date)}</dd></dl>
<aside class="note"><strong>About reported values</strong><span>GETS reported values may represent a fixed contract value or an estimated value over the life of the tender. They are not proof of what was paid.</span></aside>
{#if regions.length}<div class="chips"><strong>Regions</strong>{#each regions as region}<span>{region.region}</span>{/each}</div>{/if}
{#if categories.length}<div class="chips"><strong>Product / service categories</strong>{#each categories as category}<span>{category.unspsc_code} — {category.unspsc_description}</span>{/each}</div><p class="helper">These categories use UNSPSC codes, a standard product and service classification used in source data.</p>{/if}
<div class="supplier-links"><strong>{suppliers.length?`Successful suppliers: ${suppliers.length}`:'Successful suppliers: none'}</strong>{#each visibleSuppliers as s}<a href={`/record/${s.entity_id}`}>{s.business_name}</a>{/each}{#if suppliers.length>visibleSuppliers.length}<button class="link-button" onclick={() => showAllSuppliers = true}>Show all suppliers</button>{/if}</div>
{#if rfx.award_type==='Not Awarded'}<aside class="note"><strong>Not awarded</strong><span>This GETS record is marked Not Awarded, so NZ Records shows no successful supplier relationship for it.</span></aside>{/if}</article></section>{/if}
{#if supplier}<section class="gets"><div class="heading"><h2>GETS supplier record</h2><span>Not verified as a separate company record</span></div><article><dl class="facts"><dt>Supplier name</dt><dd>{supplier.business_name}</dd><dt>Related tender</dt><dd>{#each relatedRfx as record}<a href={`/record/${record.entity_id}`}>RFx number {record.rfx_id} — {record.title}</a>{/each}</dd><dt>Source NZBN value</dt><dd>{valueOrMissing(supplier.raw_supplier_nzbn)}</dd><dt>Source NZBN note</dt><dd>{nzbnSourceNote(supplier.nzbn_quality)}</dd><dt>Identity status</dt><dd>Not necessarily matched to a company elsewhere in NZ Records</dd></dl></article></section>{/if}
{#if sourceEvidence}<section class="gets record-source"><div class="heading"><h2>Source for this record</h2><span>Record source</span></div><article><p class="source-intro">{recordSourceIntro(sourceEvidence)}</p><dl class="facts"><dt>Published by</dt><dd>{sourcePublisher(sourceEvidence)}</dd>{#if isCharitySource(sourceEvidence)}<dt>Charity registration number</dt><dd>{valueOrMissing(sourceEvidence.record_id)}</dd>{:else}<dt>Source record ID</dt><dd>{valueOrMissing(sourceEvidence.record_id)}</dd>{/if}<dt>Source</dt><dd>{#if sourceEvidence.source_url}<a href={sourceEvidence.source_url} target="_blank" rel="noreferrer">{recordSourceLinkText(sourceEvidence)} ↗</a>{:else}Not supplied{/if}</dd>{#if sourceEvidence.licence}<dt>Licence</dt><dd>{sourceEvidence.licence}</dd>{/if}<dt>Published / source snapshot date</dt><dd>{valueOrMissing(sourceEvidence.published_at)}</dd><dt>Retrieved by NZ Records</dt><dd>{valueOrMissing(sourceEvidence.retrieved_at)}</dd></dl></article></section>{/if}
<section class="connections"><div class="heading"><h2>{isCharityOfficerRecord?'Connections for this record':'Connections'}</h2><span>{connections.length} {connections.length===1?'connection':'connections'}</span></div>
{#each visibleConnections as c}<article><div class="relationship"><span>{relationshipLabel(c.predicate,c.direction)}</span><div><a href={`/record/${c.connected_id}`}>{displayConnectedName(c)}</a><small>{connectedRecordType(c)}{c.connected_status&&!c.connected_gets_supplier_entity_id?` · ${c.connected_status}`:''}</small></div></div><details><summary>Evidence for this connection</summary><div class="evidence"><p><strong>Connection evidence</strong><a href={c.source_url} target="_blank" rel="noreferrer">{connectionPublisher(c)} ↗</a></p><dl>{#if c.record_id}<dt>Source record</dt><dd>{c.record_id}</dd>{/if}{#if c.published_at}<dt>Published</dt><dd>{c.published_at}</dd>{/if}<dt>Retrieved</dt><dd>{c.retrieved_at}</dd>{#if c.licence}<dt>Licence</dt><dd>{c.licence}</dd>{/if}</dl></div></details></article>{/each}
{#if connections.length>visibleConnections.length}<button class="show-more" onclick={() => showAllConnections = true}>Show all connections</button>{/if}
{#if connections.length===0}<div class="empty">No connections are currently loaded for this record.</div>{/if}</section>
<aside class="disclaimer"><strong>What does a connection mean?</strong><span>NZ Records shows relationships found in public records. A connection does not by itself imply wrongdoing, influence or endorsement. Check the source to see the evidence behind it.</span></aside></main>
<style>:global(*){box-sizing:border-box}:global(body){margin:0;background:#f7f7f4;color:#202624;font-family:Arial,Helvetica,sans-serif}:global(a){color:#135f50}main{max-width:960px;margin:auto;padding:38px 28px 90px}.breadcrumb{font-size:13px;color:#68726e;margin:0 0 32px}.identity{padding-bottom:35px;border-bottom:1px solid #cbd1cc}.type{font-size:14px;font-weight:700;color:#176b5a;margin:0}.identity h1{font-family:Georgia,'Times New Roman',serif;font-size:clamp(40px,6vw,58px);line-height:1.08;letter-spacing:-.025em;margin:9px 0}.status{font-size:17px;color:#58625e}.ids{display:flex;gap:45px;margin:28px 0 0;flex-wrap:wrap}.ids div{display:flex;flex-direction:column;gap:4px}.ids dt{font-size:12px;font-weight:700;color:#59635f}.ids dd{margin:0;font-size:14px}.note{max-width:750px;background:#eef4f1;border-left:5px solid #176b5a;padding:17px 20px;margin-top:28px;display:flex;flex-direction:column;gap:6px;line-height:1.5}.note span{color:#46504c}.connections,.gets{padding-top:36px}.heading{display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid #6e7873;padding-bottom:12px}.heading h2{font-family:Georgia,'Times New Roman',serif;font-size:30px;margin:0}.heading span{font-size:13px;color:#68726e}article{background:#fff;border-bottom:1px solid #d5dad6;padding:20px 16px}.relationship{display:grid;grid-template-columns:150px 1fr;gap:20px}.relationship>span{font-size:13px;font-weight:700;color:#4e5955}.relationship div{display:flex;flex-direction:column;gap:5px}.relationship a{font-size:17px;font-weight:700}.relationship small{font-size:13px;color:#69736f}details{margin:15px 0 0 170px}summary{color:#135f50;text-decoration:underline;cursor:pointer;font-size:13px}.evidence{margin-top:13px;background:#f2f4f2;border:1px solid #d1d6d2;padding:15px}.evidence p{margin:0;display:flex;flex-direction:column;gap:5px;font-size:13px}.evidence dl,.facts{display:grid;grid-template-columns:120px 1fr;gap:7px 12px;font-size:12px;margin:15px 0 0}.evidence dt,.facts dt{font-weight:700;color:#5b6561}.evidence dd,.facts dd{margin:0}.facts{grid-template-columns:160px 1fr;font-size:14px;margin:0}.facts dd{line-height:1.45}.facts dd a{display:block;font-weight:700}.chips,.supplier-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.chips strong,.supplier-links strong{width:100%;font-size:12px;color:#4e5955}.chips span{background:#eef4f1;border:1px solid #cbd1cc;border-radius:999px;padding:7px 10px;font-size:12px;color:#46504c}.supplier-links{flex-direction:column}.supplier-links a{display:flex;justify-content:space-between;gap:18px;border-top:1px solid #d5dad6;padding-top:10px;font-weight:700}.link-button,.show-more{align-self:flex-start;border:1px solid #176b5a;background:#fff;color:#135f50;font-weight:700;padding:10px 12px;cursor:pointer;text-decoration:underline}.empty{padding:30px 16px;background:#fff;color:#69736f}.disclaimer{border-top:1px solid #cbd1cc;margin-top:45px;padding-top:22px;display:flex;flex-direction:column;gap:7px;color:#59635f;line-height:1.55;font-size:13px}.disclaimer strong{color:#202624}@media(max-width:650px){.ids{flex-direction:column;gap:14px}.relationship,.facts{grid-template-columns:1fr;gap:7px}details{margin-left:0}.heading{align-items:flex-start;flex-direction:column;gap:5px}}</style>
